// n8n Code node — "Load Config", mode: Run Once for All Items.
// The build script injects config/sources.json in place of the placeholder below.
const CONFIG = {
  "settings": {
    "daysBack": 7,
    "daysForward": 90,
    "masterCalendarId": "REPLACE_WITH_MASTER_GOOGLE_CALENDAR_ID"
  },
  "sources": [
    {
      "name": "M365 Work 1",
      "type": "ics",
      "url": "https://outlook.office365.com/owa/calendar/REPLACE/calendar.ics",
      "prefix": "[W1] ",
      "enabled": true
    },
    {
      "name": "M365 Work (no ICS publishing) via Graph",
      "type": "graph",
      "prefix": "[PB] ",
      "enabled": false
    },
    {
      "name": "M365 Work 2",
      "type": "ics",
      "url": "https://outlook.office365.com/owa/calendar/REPLACE/calendar.ics",
      "prefix": "[W2] ",
      "enabled": true
    },
    {
      "name": "M365 Work 3",
      "type": "ics",
      "url": "https://outlook.office365.com/owa/calendar/REPLACE/calendar.ics",
      "prefix": "[W3] ",
      "enabled": true
    },
    {
      "name": "M365 Work 4",
      "type": "ics",
      "url": "https://outlook.office365.com/owa/calendar/REPLACE/calendar.ics",
      "prefix": "[W4] ",
      "enabled": true
    },
    {
      "name": "Google Personal",
      "type": "ics",
      "url": "https://calendar.google.com/calendar/ical/REPLACE/private-REPLACE/basic.ics",
      "prefix": "",
      "enabled": true
    }
  ]
};
return CONFIG.sources
  .filter(s => s.enabled !== false)
  .map(source => ({ json: { settings: CONFIG.settings, source } }));

// n8n Code node — "Parse Graph", mode: Run Once for Each Item.
// Input: one page of /me/calendarView (with Prefer: outlook.timezone="UTC"), paired with its "Load Config" item.
// Output: same {_kind:'batch'|'error'} shape as "Parse ICS".
const src = $('Load Config').item.json.source;

if ($json.error || !Array.isArray($json.value)) {
  return { json: { _kind: 'error', source: src.name, message: String($json.error?.message || $json.error || 'no Graph data') } };
}

const utc = s => new Date(String(s).replace(/(\.\d{3})\d*$/, '$1') + 'Z').toISOString();
const events = $json.value
  .filter(e => !e.isCancelled)
  .map(e => {
    const allDay = !!e.isAllDay;
    return {
      _kind: 'event',
      source: src.name,
      prefix: src.prefix || '',
      title: e.subject || '(no title)',
      location: e.location?.displayName || '',
      description: e.bodyPreview || '',
      allDay,
      start: utc(e.start.dateTime),
      end: utc(e.end.dateTime),
      startDate: allDay ? e.start.dateTime.slice(0, 10) : null,
      endDate: allDay ? e.end.dateTime.slice(0, 10) : null,
    };
  });

return { json: { _kind: 'batch', source: src.name, events } };

// n8n Code node — "Parse ICS", mode: Run Once for Each Item.
// Input: HTTP Request output (ICS text in $json.data) paired with the "Load Config" item.
// Output: one item per event occurrence inside the window, or an error marker.
// Needs NODE_FUNCTION_ALLOW_EXTERNAL=ical.js
const ICAL = require('ical.js');
const cfg = $('Load Config').item.json;
const { daysBack, daysForward } = cfg.settings;
const src = cfg.source;

if ($json.error || typeof $json.data !== 'string' || !$json.data.includes('BEGIN:VCALENDAR')) {
  return { json: { _kind: 'error', source: src.name, message: String($json.error?.message || 'no ICS data') } };
}

const now = Date.now();
const winStart = now - daysBack * 864e5;
const winEnd = now + daysForward * 864e5;

const root = new ICAL.Component(ICAL.parse($json.data));
root.getAllSubcomponents('vtimezone').forEach(tz => {
  try { ICAL.TimezoneService.register(tz); } catch (e) {}
});

const out = [];
const push = (ev, startT, endT) => {
  const allDay = startT.isDate;
  const s = startT.toJSDate();
  const e = endT.toJSDate();
  if (e.getTime() < winStart || s.getTime() > winEnd) return;
  out.push({ json: {
    _kind: 'event',
    source: src.name,
    prefix: src.prefix || '',
    title: ev.summary || '(no title)',
    location: ev.location || '',
    description: ev.description || '',
    allDay,
    start: s.toISOString(),
    end: e.toISOString(),
    startDate: allDay ? startT.toString() : null,
    endDate: allDay ? endT.toString() : null,
  } });
};

const masters = root.getAllSubcomponents('vevent').filter(v => !v.hasProperty('recurrence-id'));
const overrides = root.getAllSubcomponents('vevent').filter(v => v.hasProperty('recurrence-id'));
const overridden = new Set(overrides.map(v => v.getFirstPropertyValue('uid') + '|' + v.getFirstPropertyValue('recurrence-id').toJSDate().getTime()));

for (const comp of masters) {
  const ev = new ICAL.Event(comp);
  if (comp.getFirstPropertyValue('status') === 'CANCELLED') continue;
  if (ev.isRecurring()) {
    const it = ev.iterator();
    let next, guard = 0;
    while ((next = it.next()) && guard++ < 2000) {
      if (next.toJSDate().getTime() > winEnd) break;
      if (overridden.has(ev.uid + '|' + next.toJSDate().getTime())) continue;
      const d = ev.getOccurrenceDetails(next);
      push(ev, d.startDate, d.endDate);
    }
  } else {
    push(ev, ev.startDate, ev.endDate);
  }
}
for (const comp of overrides) {
  if (comp.getFirstPropertyValue('status') === 'CANCELLED') continue;
  const ev = new ICAL.Event(comp);
  push(ev, ev.startDate, ev.endDate);
}

// Run-once-for-each-item must return one item; wrap list so Dedupe can flatten.
return { json: { _kind: 'batch', source: src.name, events: out.map(o => o.json) } };

// n8n Code node — "Dedupe & Diff", mode: Run Once for All Items.
// Input (merged): per-source batches from "Parse ICS" ({_kind:'batch', events:[...]})
//   plus one item from "Get Master Events" ({items:[...]} from the Google Calendar API).
// Output: one item per write needed: {action:'create'|'update'|'delete', calendarId, id, body?}

// cyrb53 string hash (two seeds -> ~28 hex chars). Google event ids allow [a-v0-9], hex is a subset.
function cyrb53(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
}
const hash = s => cyrb53(s, 1) + cyrb53(s, 2);
const norm = t => String(t).toLowerCase().replace(/\s+/g, ' ').trim();

function computeDiff(batches, masterItems, settings, sourceErrors) {
  // 1. dedupe — first source listed wins
  const desired = new Map();
  const seen = new Set();
  for (const b of batches) {
    for (const e of b.events) {
      const key = norm(e.title) + '|' + (e.allDay ? e.startDate + '/' + e.endDate : e.start + '/' + e.end);
      if (seen.has(key)) continue;
      seen.add(key);
      const id = 'cs' + hash(key);
      const body = {
        id,
        summary: (e.prefix || '') + e.title,
        location: e.location || undefined,
        description: ((e.description || '') + '\n\n[calSync source: ' + e.source + ']').trim(),
        start: e.allDay ? { date: e.startDate } : { dateTime: e.start },
        end: e.allDay ? { date: e.endDate } : { dateTime: e.end },
      };
      body.extendedProperties = { private: { calSync: '1', contentHash: hash(JSON.stringify(body)) } };
      desired.set(id, body);
    }
  }

  // 2. diff against what calSync previously wrote to the master
  const existing = new Map(masterItems.map(m => [m.id, m]));
  const out = [];
  const calendarId = settings.masterCalendarId;
  for (const [id, body] of desired) {
    const ex = existing.get(id);
    if (!ex) out.push({ action: 'create', calendarId, id, body });
    else if (ex.extendedProperties?.private?.contentHash !== body.extendedProperties.private.contentHash || ex.status === 'cancelled')
      out.push({ action: 'update', calendarId, id, body });
  }
  // 3. deletions — skipped if any source failed or nothing came back (avoid wiping master on an outage)
  if (sourceErrors === 0 && desired.size > 0) {
    for (const id of existing.keys()) if (!desired.has(id)) out.push({ action: 'delete', calendarId, id });
  }
  return out;
}

if (typeof module !== 'undefined') module.exports = { computeDiff, hash, norm };

if (typeof $input !== 'undefined') {
  const settings = $('Load Config').first().json.settings;
  const all = $input.all().map(i => i.json);
  const batches = all.filter(j => j._kind === 'batch');
  const sourceErrors = all.filter(j => j._kind === 'error').length;
  const masterItems = all.filter(j => Array.isArray(j.items)).flatMap(j => j.items);
  const diff = computeDiff(batches, masterItems, settings, sourceErrors);
  if (diff.length === 0) return [{ json: { action: 'noop', sourceErrors } }];
  return diff.map(d => ({ json: d }));
}
